import{_ as t,o as a,c as r,a2 as o}from"./chunks/framework.Dxeykp0S.js";const p=JSON.parse('{"title":"Day 2 · 认证与安全：OAuth2、JWT 与后端安全必修课","description":"","frontmatter":{},"headers":[],"relativePath":"pro/02-auth-security.md","filePath":"pro/02-auth-security.md","lastUpdated":1787141678000}'),l={name:"pro/02-auth-security.md"};function i(d,e,s,c,h,n){return a(),r("div",null,[...e[0]||(e[0]=[o('<h1 id="day-2-·-认证与安全-oauth2、jwt-与后端安全必修课" tabindex="-1">Day 2 · 认证与安全：OAuth2、JWT 与后端安全必修课 <a class="header-anchor" href="#day-2-·-认证与安全-oauth2、jwt-与后端安全必修课" aria-label="Permalink to &quot;Day 2 · 认证与安全：OAuth2、JWT 与后端安全必修课&quot;">​</a></h1><h2 id="前言" tabindex="-1">前言 <a class="header-anchor" href="#前言" aria-label="Permalink to &quot;前言&quot;">​</a></h2><p>认证授权是后端的护城河。FastAPI 内置了完整的 OAuth2 工具链（<code>OAuth2PasswordBearer</code>、<code>Security</code> 作用域），配合 PyJWT 和密码哈希库，你可以实现生产级的认证体系。今天顺便把后端安全的常见坑（时序攻击、CORS、限流）一并扫掉。</p><h2 id="课程目标" tabindex="-1">课程目标 <a class="header-anchor" href="#课程目标" aria-label="Permalink to &quot;课程目标&quot;">​</a></h2><ul><li>实现 OAuth2 Password Flow + JWT 的完整认证</li><li>掌握密码哈希（bcrypt/argon2）与常数时间比较</li><li>理解 FastAPI 的 <code>Security</code> 依赖与作用域（scopes）权限模型</li><li>配置 CORS、限流、安全响应头</li></ul><h2 id="阅读学习" tabindex="-1">阅读学习 <a class="header-anchor" href="#阅读学习" aria-label="Permalink to &quot;阅读学习&quot;">​</a></h2><ul><li><a href="https://fastapi.tiangolo.com/zh/tutorial/security/" target="_blank" rel="noreferrer">FastAPI 官方：Security 章节</a>（从 First Steps 读到 OAuth2 scopes，质量极高）</li><li><a href="https://jwt.io/introduction" target="_blank" rel="noreferrer">JWT.io 介绍</a></li><li>对照速览：</li></ul><table tabindex="0"><thead><tr><th>Node 生态</th><th>Python 生态</th></tr></thead><tbody><tr><td><code>jsonwebtoken</code></td><td><code>PyJWT</code></td></tr><tr><td><code>bcrypt</code> / <code>argon2</code> npm 包</td><td><code>pwdlib[argon2]</code>（FastAPI 官方文档同款）</td></tr><tr><td>passport.js</td><td>没有对应物，FastAPI Security 依赖注入就是答案</td></tr><tr><td><code>express-rate-limit</code></td><td><code>slowapi</code></td></tr></tbody></table><h2 id="任务作业" tabindex="-1">任务作业 <a class="header-anchor" href="#任务作业" aria-label="Permalink to &quot;任务作业&quot;">​</a></h2><ol><li><p><strong>完整认证链路</strong>：在昨天的任务管理 API 上实现：</p><ul><li><code>POST /auth/register</code>：注册（密码用 <code>pwdlib[argon2]</code> 的 <code>PasswordHash.recommended()</code> 哈希存储，<strong>绝不存明文</strong>）</li><li><code>POST /auth/token</code>：OAuth2 password flow 登录，签发 JWT（access token 30 分钟 + refresh token 7 天）</li><li><code>get_current_user</code> 依赖升级为验证 JWT 签名与过期时间</li><li>所有 tasks 路由挂上用户隔离：只能看到自己的任务</li></ul></li><li><p><strong>作用域权限</strong>：实现基于 OAuth2 scopes 的权限控制：<code>tasks:read</code> / <code>tasks:write</code> 两个 scope，管理员用户拥有全部 scope，普通用户只有 read。用 <code>Security(get_current_user, scopes=[...])</code> 声明，理解 token 中 scope 的校验逻辑。</p></li><li><p><strong>refresh token 轮换</strong>：实现 <code>POST /auth/refresh</code>：用 refresh token 换新 access token，并使旧 refresh token 失效（存储 jti 到数据库或 Redis）。思考：为什么 refresh token 要设计成可吊销的？</p></li><li><p><strong>安全加固清单</strong>：</p><ul><li>CORS：配置 <code>CORSMiddleware</code>，只允许指定域名，理解 preflight</li><li>限流：<code>uv add slowapi</code>，给登录接口加 5 次/分钟限流（防爆破）</li><li>常数时间比较：了解 <code>secrets.compare_digest</code> 的用途（防时序攻击）</li><li>密码强度校验：用 pydantic validator 强制密码复杂度</li></ul></li></ol><h2 id="自测问题" tabindex="-1">自测问题 <a class="header-anchor" href="#自测问题" aria-label="Permalink to &quot;自测问题&quot;">​</a></h2><ul><li>JWT 签名保证了什么、<strong>不</strong>保证什么？为什么敏感信息不能放 payload？</li><li>access token 和 refresh token 分离的设计解决了什么问题？</li><li>bcrypt/argon2 为什么比 SHA-256 适合存密码？（加盐、慢哈希、work factor）为什么现在更推荐 Argon2？</li><li>OAuth2 的 password flow 为什么不推荐用于第三方应用？它适合什么场景？</li><li>把 JWT 存 localStorage 还是 httpOnly cookie？各自防的是什么攻击（XSS vs CSRF）？</li></ul><h2 id="总结" tabindex="-1">总结 <a class="header-anchor" href="#总结" aria-label="Permalink to &quot;总结&quot;">​</a></h2><p>记录今天的学习笔记。</p><h2 id="拓展阅读" tabindex="-1">拓展阅读 <a class="header-anchor" href="#拓展阅读" aria-label="Permalink to &quot;拓展阅读&quot;">​</a></h2><ul><li><a href="https://owasp.org/API-Security/editions/2023/en/0x11-t10/" target="_blank" rel="noreferrer">OWASP API Security Top 10</a></li><li><a href="https://datatracker.ietf.org/doc/html/rfc9068" target="_blank" rel="noreferrer">RFC 9068：JWT Profile for OAuth 2.0 Access Tokens</a></li></ul><h2 id="预告" tabindex="-1">预告 <a class="header-anchor" href="#预告" aria-label="Permalink to &quot;预告&quot;">​</a></h2><p>下一节 <a href="./03-cache-tasks">Day 3 · 缓存与后台任务</a>：用 Redis 实现缓存，再用 Celery 处理异步任务。</p>',18)])])}const f=t(l,[["render",i]]);export{p as __pageData,f as default};
